type History={past:Project[];present:Project;future:Project[]};
type HistoryAction={type:'commit';project:Project}|{type:'undo'}|{type:'redo'}|{type:'replace';project:Project};
function historyReducer(state:History,action:HistoryAction):History {
  if(action.type==='replace')return {past:[],present:action.project,future:[]};
  if(action.type==='undo'){if(!state.past.length)return state;return {past:state.past.slice(0,-1),present:state.past[state.past.length-1],future:[state.present,...state.future].slice(0,60)};}
  if(action.type==='redo'){if(!state.future.length)return state;return {past:[...state.past,state.present].slice(-60),present:state.future[0],future:state.future.slice(1)};}
  return {past:[...state.past,state.present].slice(-60),present:{...action.project,updatedAt:new Date().toISOString()},future:[]};
}
